/**
 * Saved launch intent as pure, validated data. Persistence, identity generation, and I/O belong to
 * their callers; this module owns the closed value contract and optimistic mutation semantics.
 */

import {type HostKey, hostFromKey, hostKey, validHostPath} from '@vibesys/hosts';
import {isTaskName} from './ids.js';
import {canonicalShellWords} from './shell-words.js';

declare const PROFILE_ID: unique symbol;
declare const PROFILE_ARGUMENTS: unique symbol;

/** A stable opaque identity generated by the settings shell (a canonical UUID). */
export type LaunchProfileId = string & {readonly [PROFILE_ID]: true};

/** A validated, immutable command argument vector. */
export type LaunchArguments = readonly string[] & {readonly [PROFILE_ARGUMENTS]: true};

export const LAUNCH_PROFILE_LIMIT = 32;
export const LAUNCH_PROFILE_LABEL_CODE_POINT_LIMIT = 80;
export const LAUNCH_PROFILE_LABEL_BYTE_LIMIT = 240;
export const LAUNCH_ARGUMENT_COUNT_LIMIT = 128;
export const LAUNCH_ARGUMENT_BYTE_LIMIT = 4_096;
export const LAUNCH_ARGUMENT_TOTAL_BYTE_LIMIT = 16_384;

const PROFILE_KEYS = ['id', 'revision', 'label', 'host', 'project', 'task', 'arguments'] as const;
const DRAFT_KEYS = ['label', 'host', 'project', 'task', 'arguments'] as const;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const LINE_BREAK_OR_NUL = /[\0\n\r\u2028\u2029]/;

export class LaunchProfileValidationError extends Error {
  override name = 'LaunchProfileValidationError';
}

export class LaunchProfileConflictError extends Error {
  override name = 'LaunchProfileConflictError';
}

export interface LaunchProfileDraft {
  readonly label: string;
  readonly host: HostKey;
  readonly project: string;
  readonly task: string;
  readonly arguments: LaunchArguments;
}

export interface LaunchProfile extends LaunchProfileDraft {
  readonly id: LaunchProfileId;
  /** Starts at one and advances for every successful rename. */
  readonly revision: number;
}

export type LaunchProfileMutation =
  | {readonly kind: 'save'; readonly id: LaunchProfileId; readonly profile: LaunchProfileDraft}
  | {
      readonly kind: 'rename';
      readonly id: LaunchProfileId;
      readonly revision: number;
      readonly label: string;
    }
  | {readonly kind: 'delete'; readonly id: LaunchProfileId; readonly revision: number};

/** Parse one canonical UUID into the opaque profile-id type. */
export function launchProfileId(value: unknown, path = 'launch profile id'): LaunchProfileId {
  if (typeof value !== 'string' || !UUID.test(value)) {
    throw new LaunchProfileValidationError(`${path} must be a lowercase canonical UUID`);
  }
  return value as LaunchProfileId;
}

/** Validate and copy an argument vector, including count and UTF-8 byte bounds. */
export function launchArguments(value: unknown, path = 'launch arguments'): LaunchArguments {
  const tokens = strictList(value, path, 'a list of strings');
  if (tokens.length > LAUNCH_ARGUMENT_COUNT_LIMIT) {
    throw new LaunchProfileValidationError(
      `${path} must contain at most ${LAUNCH_ARGUMENT_COUNT_LIMIT} tokens`,
    );
  }
  let totalBytes = 0;
  const parsed = tokens.map((token, index) => {
    const tokenPath = `${path}[${index}]`;
    if (typeof token !== 'string') {
      throw new LaunchProfileValidationError(`${tokenPath} must be a string`);
    }
    if (LINE_BREAK_OR_NUL.test(token)) {
      throw new LaunchProfileValidationError(`${tokenPath} must be one line and contain no NUL`);
    }
    const bytes = utf8Bytes(token, tokenPath);
    if (bytes > LAUNCH_ARGUMENT_BYTE_LIMIT) {
      throw new LaunchProfileValidationError(
        `${tokenPath} must be at most ${LAUNCH_ARGUMENT_BYTE_LIMIT} UTF-8 bytes`,
      );
    }
    totalBytes += bytes;
    return token;
  });
  if (totalBytes > LAUNCH_ARGUMENT_TOTAL_BYTE_LIMIT) {
    throw new LaunchProfileValidationError(
      `${path} must total at most ${LAUNCH_ARGUMENT_TOTAL_BYTE_LIMIT} UTF-8 bytes`,
    );
  }
  return Object.freeze(parsed) as LaunchArguments;
}

/** Parse the form value that can be saved as a new profile. Unknown and inherited keys fail. */
export function parseLaunchProfileDraft(
  value: unknown,
  path = 'launch profile',
): LaunchProfileDraft {
  const record = strictRecord(value, DRAFT_KEYS, path);
  return freezeDraft({
    label: profileLabel(record['label'], `${path}.label`),
    host: profileHost(record['host'], `${path}.host`),
    project: profileProject(record['project'], `${path}.project`),
    task: profileTask(record['task'], `${path}.task`),
    arguments: launchArguments(record['arguments'], `${path}.arguments`),
  });
}

/** Parse one persisted or IPC profile. Unknown and inherited keys fail with their exact path. */
export function parseLaunchProfile(value: unknown, path = 'launch profile'): LaunchProfile {
  const record = strictRecord(value, PROFILE_KEYS, path);
  return freezeProfile({
    id: launchProfileId(record['id'], `${path}.id`),
    revision: profileRevision(record['revision'], `${path}.revision`),
    label: profileLabel(record['label'], `${path}.label`),
    host: profileHost(record['host'], `${path}.host`),
    project: profileProject(record['project'], `${path}.project`),
    task: profileTask(record['task'], `${path}.task`),
    arguments: launchArguments(record['arguments'], `${path}.arguments`),
  });
}

/** Parse a complete authoritative list, enforcing its bound and unique stable identities. */
export function parseLaunchProfiles(
  value: unknown,
  path = 'launch profiles',
): readonly LaunchProfile[] {
  const values = strictList(value, path, 'a list');
  if (values.length > LAUNCH_PROFILE_LIMIT) {
    throw new LaunchProfileValidationError(
      `${path} must contain at most ${LAUNCH_PROFILE_LIMIT} profiles`,
    );
  }
  const ids = new Set<string>();
  const profiles = values.map((profile, index) => {
    const parsed = parseLaunchProfile(profile, `${path}[${index}]`);
    if (ids.has(parsed.id)) {
      throw new LaunchProfileValidationError(`${path}[${index}].id duplicates ${parsed.id}`);
    }
    ids.add(parsed.id);
    return parsed;
  });
  return Object.freeze(profiles);
}

/** Canonical one-line summary of a validated argument vector. */
export function canonicalLaunchArguments(value: unknown): string {
  return canonicalShellWords(launchArguments(value));
}

/**
 * Apply one optimistic mutation. A stale or missing identity throws without changing `profiles`;
 * successful mutations return a newly validated, immutable authoritative list.
 */
export function applyLaunchProfileMutation(
  profilesValue: unknown,
  mutation: LaunchProfileMutation,
): readonly LaunchProfile[] {
  const profiles = parseLaunchProfiles(profilesValue);
  switch (mutation.kind) {
    case 'save': {
      const id = launchProfileId(mutation.id);
      if (profiles.some(profile => profile.id === id)) {
        throw new LaunchProfileConflictError(`launch profile ${id} already exists`);
      }
      if (profiles.length >= LAUNCH_PROFILE_LIMIT) {
        throw new LaunchProfileConflictError(
          `at most ${LAUNCH_PROFILE_LIMIT} launch profiles can be saved`,
        );
      }
      const draft = parseLaunchProfileDraft(mutation.profile);
      const profile = parseLaunchProfile({...draft, id, revision: 1});
      return Object.freeze([...profiles, profile]);
    }
    case 'rename': {
      const found = expectedProfile(profiles, mutation.id, mutation.revision);
      if (found.revision === Number.MAX_SAFE_INTEGER) {
        throw new LaunchProfileConflictError(`launch profile ${found.id} cannot be revised again`);
      }
      const renamed = freezeProfile({
        ...found,
        revision: found.revision + 1,
        label: profileLabel(mutation.label, 'launch profile label'),
      });
      return Object.freeze(profiles.map(profile => (profile.id === found.id ? renamed : profile)));
    }
    case 'delete': {
      const found = expectedProfile(profiles, mutation.id, mutation.revision);
      return Object.freeze(profiles.filter(profile => profile.id !== found.id));
    }
  }
}

function expectedProfile(
  profiles: readonly LaunchProfile[],
  idValue: unknown,
  revisionValue: unknown,
): LaunchProfile {
  const id = launchProfileId(idValue);
  const revision = profileRevision(revisionValue, 'launch profile revision');
  const found = profiles.find(profile => profile.id === id);
  if (found === undefined)
    throw new LaunchProfileConflictError(`launch profile ${id} no longer exists`);
  if (found.revision !== revision) {
    throw new LaunchProfileConflictError(
      `launch profile ${id} is revision ${found.revision}, not ${revision}`,
    );
  }
  return found;
}

function profileRevision(value: unknown, path: string): number {
  if (!Number.isSafeInteger(value) || (value as number) < 1) {
    throw new LaunchProfileValidationError(`${path} must be a positive safe integer`);
  }
  return value as number;
}

function profileLabel(value: unknown, path: string): string {
  if (typeof value !== 'string') throw new LaunchProfileValidationError(`${path} must be a string`);
  if (value === '') throw new LaunchProfileValidationError(`${path} must not be empty`);
  if (value.trim() !== value || LINE_BREAK_OR_NUL.test(value)) {
    throw new LaunchProfileValidationError(
      `${path} must be one line, contain no NUL, and have no surrounding whitespace`,
    );
  }
  if ([...value].length > LAUNCH_PROFILE_LABEL_CODE_POINT_LIMIT) {
    throw new LaunchProfileValidationError(
      `${path} must be at most ${LAUNCH_PROFILE_LABEL_CODE_POINT_LIMIT} characters`,
    );
  }
  if (utf8Bytes(value, path) > LAUNCH_PROFILE_LABEL_BYTE_LIMIT) {
    throw new LaunchProfileValidationError(
      `${path} must be at most ${LAUNCH_PROFILE_LABEL_BYTE_LIMIT} UTF-8 bytes`,
    );
  }
  return value;
}

function profileHost(value: unknown, path: string): HostKey {
  try {
    return hostKey(hostFromKey(value));
  } catch (error) {
    throw new LaunchProfileValidationError(`${path}: ${(error as Error).message}`);
  }
}

function profileProject(value: unknown, path: string): string {
  try {
    return validHostPath(value, path);
  } catch (error) {
    throw new LaunchProfileValidationError((error as Error).message);
  }
}

function profileTask(value: unknown, path: string): string {
  if (!isTaskName(value)) {
    throw new LaunchProfileValidationError(
      `${path} must be 1-128 lowercase letters, digits, ".", "_", or "-", starting with a letter or digit`,
    );
  }
  return value;
}

function strictRecord<const Keys extends readonly string[]>(
  value: unknown,
  allowed: Keys,
  path: string,
): Readonly<Record<string, unknown>> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new LaunchProfileValidationError(`${path} must be an object`);
  }
  const record = value as Readonly<Record<string, unknown>>;
  assertPlainRecordPrototype(record, path);
  assertAllowedRecordKeys(record, allowed, path);
  assertRequiredRecordKeys(record, allowed, path);
  return record;
}

function assertPlainRecordPrototype(record: Readonly<Record<string, unknown>>, path: string): void {
  const prototype = Object.getPrototypeOf(record) as object | null;
  if (prototype === null || prototype === Object.prototype) return;
  for (let current: object | null = prototype; current !== null; ) {
    if (current === Object.prototype) break;
    const inheritedKey = Reflect.ownKeys(current).find(
      (key): key is string => typeof key === 'string',
    );
    if (inheritedKey !== undefined) {
      throw new LaunchProfileValidationError(`${path}.${inheritedKey} must not be inherited`);
    }
    current = Object.getPrototypeOf(current) as object | null;
  }
  throw new LaunchProfileValidationError(`${path} must have a plain-object prototype`);
}

function assertAllowedRecordKeys(
  record: Readonly<Record<string, unknown>>,
  allowed: readonly string[],
  path: string,
): void {
  for (const key in record) {
    if (!Object.hasOwn(record, key)) {
      throw new LaunchProfileValidationError(`${path}.${key} must not be inherited`);
    }
  }
  for (const key of Reflect.ownKeys(record)) {
    if (typeof key !== 'string') {
      throw new LaunchProfileValidationError(`${path} must not contain symbol keys`);
    }
    if (!(allowed as readonly string[]).includes(key)) {
      throw new LaunchProfileValidationError(`${path}.${key} is not allowed`);
    }
  }
}

function assertRequiredRecordKeys(
  record: Readonly<Record<string, unknown>>,
  allowed: readonly string[],
  path: string,
): void {
  for (const key of allowed) {
    if (!Object.hasOwn(record, key)) {
      throw new LaunchProfileValidationError(`${path}.${key} must be provided`);
    }
  }
}

function strictList(value: unknown, path: string, expected: string): readonly unknown[] {
  if (!Array.isArray(value)) {
    throw new LaunchProfileValidationError(`${path} must be ${expected}`);
  }
  assertStandardArrayPrototype(value, path);
  assertDenseArrayIndices(value, path);
  assertOnlyArrayIndices(value, path);
  return value;
}

function assertStandardArrayPrototype(value: readonly unknown[], path: string): void {
  const prototype = Object.getPrototypeOf(value) as object | null;
  if (prototype === Array.prototype) return;
  throw new LaunchProfileValidationError(`${path} must have the standard array prototype`);
}

function assertDenseArrayIndices(value: readonly unknown[], path: string): void {
  for (let index = 0; index < value.length; index += 1) {
    if (Object.hasOwn(value, index)) continue;
    if (index in value) {
      throw new LaunchProfileValidationError(`${path}[${index}] must not be inherited`);
    }
    throw new LaunchProfileValidationError(`${path}[${index}] must be provided`);
  }
}

function assertOnlyArrayIndices(value: readonly unknown[], path: string): void {
  for (const key of Reflect.ownKeys(value)) {
    if (key === 'length') continue;
    if (typeof key !== 'string') {
      throw new LaunchProfileValidationError(`${path} must not contain symbol keys`);
    }
    if (!isArrayIndex(key, value.length)) {
      throw new LaunchProfileValidationError(`${path}.${key} is not allowed`);
    }
  }
}

function isArrayIndex(key: string, length: number): boolean {
  if (!/^(0|[1-9][0-9]*)$/.test(key)) return false;
  const index = Number(key);
  return Number.isSafeInteger(index) && index < length;
}

function utf8Bytes(value: string, path: string): number {
  let bytes = 0;
  for (let index = 0; index < value.length; index += 1) {
    const unit = utf8CodeUnit(value.charCodeAt(index), value.charCodeAt(index + 1), path);
    bytes += unit.bytes;
    index += unit.extraUnits;
  }
  return bytes;
}

function utf8CodeUnit(
  first: number,
  second: number,
  path: string,
): {readonly bytes: number; readonly extraUnits: number} {
  if (first >= 0xd800 && first <= 0xdbff) {
    if (second >= 0xdc00 && second <= 0xdfff) return {bytes: 4, extraUnits: 1};
    throw new LaunchProfileValidationError(`${path} must contain valid Unicode`);
  }
  if (first >= 0xdc00 && first <= 0xdfff) {
    throw new LaunchProfileValidationError(`${path} must contain valid Unicode`);
  }
  if (first <= 0x7f) return {bytes: 1, extraUnits: 0};
  if (first <= 0x7ff) return {bytes: 2, extraUnits: 0};
  return {bytes: 3, extraUnits: 0};
}

function freezeDraft(draft: LaunchProfileDraft): LaunchProfileDraft {
  return Object.freeze({
    ...draft,
    arguments: Object.freeze([...draft.arguments]) as LaunchArguments,
  });
}

function freezeProfile(profile: LaunchProfile): LaunchProfile {
  return Object.freeze({
    ...profile,
    arguments: Object.freeze([...profile.arguments]) as LaunchArguments,
  });
}
